def priority(task, state, c=2.0, alpha=1.0, beta=1.0, gamma=0.5):
    wait = state.now - task.release
    est = max(task.estimated_runtime, 1e-6)
    ratio = wait / est
    load = state.queue_work / max(state.capacity, 1e-6)
    rn = task.resource_need / max(state.capacity, 1e-6)
    eff_c = c / (1.0 + gamma * load + beta * rn)
    if ratio >= eff_c:
        return 1e9 + alpha * (ratio - eff_c) + 1.0 / est + beta * rn
    elif ratio >= 1.0:
        return 1e6 + 1.0 / est + beta * rn
    else:
        return 1.0 / est  # tuned (c=0.528,alpha=2.31,beta=0.912,gamma=1.94)

