def priority(task, state, c=2.0, a=1.0, beta=1.0, gamma=0.5, p=2.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    res = task.resource_need / max(state.capacity, 1e-6)
    c_eff = max(0.5, c - beta * res)
    cr = c_eff - wait / est
    if cr <= 0.0:
        excess = -cr * est
        return 1e9 + excess / est + gamma * res
    return (1.0 + a * (1.0 / (cr + 1e-6)) ** p) / est  # tuned (c=1.76,a=1.08,beta=0.823,gamma=0.135,p=0.689)

